pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0xdead)); // avoid magic collisions
        vm.prank(address(this)); // owner is the test contract after setUp
        c.transferOwnership(newOwner);
        assertTrue(c.owner() != address(0));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        // Transfer ownership to any address (including zero).
        // The reference contract must revert when newOwner is zero;
        // the buggy contract accepts it.
        bool success;
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }

        // After any transfer attempt, either it reverted (for zero in ref, for none in bug),
        // or it succeeded and the new owner must be non-zero only in the reference.
        // Here we assert the universal rule: if the call succeeded, the new owner cannot be address(0).
        // The reference always holds this (it never succeeds with zero), the buggy breaks it.
        assertTrue(!success || c.owner() != address(0));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        vm.assume(c.owner() != newOwner);
        c.transferOwnership(newOwner);
        assertTrue(c.owner() != address(0));
    }
}
